{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.hit_product_info_inv as WITH meta_map AS ( SELECT upper(IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) )) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta1 END), MIN(meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta2 END), MIN(meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta3 END), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), all_sales AS ( SELECT date, sku_group, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1, 2 UNION ALL SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, style_ sku_group, SUM(TRY_TO_NUMBER(REPLACE(sales, \',\', \'\'))) AS qty FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date >= 20230101 GROUP BY 1, 2 UNION ALL SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, style_ sku_group, SUM(TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))) AS qty FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1, 2 ), daily_sales AS ( SELECT date, sku_group, SUM(qty) AS daily_qty FROM all_sales GROUP BY 1, 2 ), raw_inwards AS ( SELECT upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, \"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) = \'new inward\' GROUP BY 1, 2 HAVING SUM(\"PUTAWAY_COMPLETED_QUANTITY\") >= 100 ), inward_with_gap AS ( SELECT sku_group, inward_date, inward_qty, LAG(inward_date) OVER ( PARTITION BY sku_group ORDER BY inward_date ) AS prev_inward_date, DATEDIFF(\'day\', LAG(inward_date) OVER (PARTITION BY sku_group ORDER BY inward_date), inward_date ) AS days_since_prev FROM raw_inwards ), inward_batch_flag AS ( SELECT sku_group, inward_date, inward_qty, CASE WHEN prev_inward_date IS NULL THEN 1 WHEN days_since_prev >= 60 THEN 1 ELSE 0 END AS is_new_batch FROM inward_with_gap ), inward_batches_raw AS ( SELECT sku_group, inward_date, inward_qty, SUM(is_new_batch) OVER ( PARTITION BY sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS batch_number FROM inward_batch_flag ), inward_batches AS ( SELECT sku_group, batch_number, MIN(inward_date) AS batch_inward_date, SUM(inward_qty) AS batch_inward_qty FROM inward_batches_raw GROUP BY 1, 2 ), sku_noos_flag AS ( SELECT sku_group, COUNT(DISTINCT batch_number) AS total_batches, MAX(batch_inward_date) AS latest_inward_date, MIN(batch_inward_date) AS first_inward_date, CASE WHEN COUNT(DISTINCT batch_number) >= 2 THEN 1 ELSE 0 END AS is_noos FROM inward_batches GROUP BY 1 ), inward_batches_windowed AS ( SELECT ib.sku_group, ib.batch_number, ib.batch_inward_date, ib.batch_inward_qty, COALESCE( DATEADD(\'day\', -1, LEAD(ib.batch_inward_date) OVER ( PARTITION BY ib.sku_group ORDER BY ib.batch_number ) ), CURRENT_DATE() ) AS batch_window_end FROM inward_batches ib ), batch_sales AS ( SELECT ibw.sku_group, ibw.batch_number, ibw.batch_inward_date, ibw.batch_inward_qty, ibw.batch_window_end, ds.date AS sale_date, ds.daily_qty, SUM(ds.daily_qty) OVER ( PARTITION BY ibw.sku_group, ibw.batch_number ORDER BY ds.date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_sales_in_window FROM inward_batches_windowed ibw JOIN daily_sales ds ON ds.sku_group = ibw.sku_group AND ds.date >= ibw.batch_inward_date AND ds.date <= ibw.batch_window_end ), batch_milestones AS ( SELECT sku_group, batch_number, batch_inward_date, batch_inward_qty, batch_window_end, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty * 0.30 THEN DATEDIFF(\'day\', batch_inward_date, sale_date) END) AS days_to_30pct, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty * 0.60 THEN DATEDIFF(\'day\', batch_inward_date, sale_date) END) AS days_to_60pct, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty * 0.90 THEN DATEDIFF(\'day\', batch_inward_date, sale_date) END) AS days_to_90pct, MAX(cum_sales_in_window) AS total_sold_in_window FROM batch_sales GROUP BY 1, 2, 3, 4, 5 ), batch_with_meta AS ( SELECT bm.*, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, mm.cogs, nf.is_noos, nf.total_batches, DATEDIFF(\'day\', bm.batch_inward_date, LEAST(bm.batch_window_end, CURRENT_DATE())) AS days_in_market FROM batch_milestones bm LEFT JOIN meta_map mm ON mm.sku_group_clean = upper(IFF( UPPER(REPLACE(bm.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(bm.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(bm.SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(bm.SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(bm.SKU_GROUP, \' \', \'\'), \'-\', 1) )) LEFT JOIN sku_noos_flag nf ON bm.sku_group = nf.sku_group ), category_benchmarks AS ( SELECT l1_category, category, AVG(days_to_30pct) AS avg_days_to_30pct, AVG(days_to_60pct) AS avg_days_to_60pct, AVG(days_to_90pct) AS avg_days_to_90pct FROM batch_with_meta WHERE days_to_90pct IS NOT NULL GROUP BY 1, 2 ), batch_scored AS ( SELECT bwm.*, cb.avg_days_to_30pct, cb.avg_days_to_60pct, cb.avg_days_to_90pct, (CASE WHEN bwm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END ) AS metrics_available, (CASE WHEN bwm.days_to_30pct IS NOT NULL AND bwm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL AND bwm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL AND bwm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END ) AS metrics_beating_avg, CASE WHEN bwm.is_noos = 1 THEN \'NOOS\' WHEN bwm.days_to_30pct IS NULL AND bwm.total_sold_in_window < bwm.batch_inward_qty * 0.30 THEN \'New\' ELSE \'Established\' END AS product_type, CASE WHEN bwm.is_noos = 1 THEN 1 WHEN (CASE WHEN bwm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END) = 0 THEN 0 WHEN (CASE WHEN bwm.days_to_30pct IS NOT NULL AND bwm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL AND bwm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL AND bwm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END ) >= 2 THEN 1 WHEN (CASE WHEN bwm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END) = 1 AND (CASE WHEN bwm.days_to_30pct IS NOT NULL AND bwm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_60pct IS NOT NULL AND bwm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN bwm.days_to_90pct IS NOT NULL AND bwm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END ) = 1 THEN 1 ELSE 0 END AS batch_is_hit FROM batch_with_meta bwm LEFT JOIN category_benchmarks cb ON bwm.l1_category = cb.l1_category AND bwm.category = cb.category ), sku_level AS ( SELECT sku_group, l1_category, category, meta1, meta2, meta3, cogs, is_noos, total_batches, MAX(CASE WHEN batch_number = total_batches THEN batch_inward_date END) AS latest_inward_date, MAX(CASE WHEN batch_number = total_batches THEN batch_inward_qty END) AS latest_batch_qty, MAX(CASE WHEN batch_number = 1 THEN batch_inward_date END) AS first_inward_date, MAX(CASE WHEN batch_number = total_batches THEN days_to_30pct END) AS days_to_30pct, MAX(CASE WHEN batch_number = total_batches THEN days_to_60pct END) AS days_to_60pct, MAX(CASE WHEN batch_number = total_batches THEN days_to_90pct END) AS days_to_90pct, MAX(CASE WHEN batch_number = total_batches THEN avg_days_to_30pct END) AS avg_days_to_30pct, MAX(CASE WHEN batch_number = total_batches THEN avg_days_to_60pct END) AS avg_days_to_60pct, MAX(CASE WHEN batch_number = total_batches THEN avg_days_to_90pct END) AS avg_days_to_90pct, MAX(CASE WHEN batch_number = total_batches THEN metrics_available END) AS metrics_available, MAX(CASE WHEN batch_number = total_batches THEN metrics_beating_avg END) AS metrics_beating_avg, MAX(CASE WHEN batch_number = total_batches THEN product_type END) AS product_type, SUM(batch_is_hit) AS batches_hit, CASE WHEN is_noos = 1 THEN 1 ELSE MAX(CASE WHEN batch_number = total_batches THEN batch_is_hit END) END AS is_hit FROM batch_scored GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ) SELECT s.SKU_Group, s.l1_category, s.category, s.meta1, s.meta2, s.meta3, s.cogs, s.product_type, s.is_noos, s.total_batches, CASE WHEN s.is_noos = 1 THEN s.batches_hit || \' of \' || s.total_batches || \' batches hit\' ELSE NULL END AS noos_hit_consistency, s.first_inward_date, s.latest_inward_date, s.latest_batch_qty, s.days_to_30pct, s.days_to_60pct, s.days_to_90pct, ROUND(s.avg_days_to_30pct, 1) AS avg_days_to_30pct, ROUND(s.avg_days_to_60pct, 1) AS avg_days_to_60pct, ROUND(s.avg_days_to_90pct, 1) AS avg_days_to_90pct, s.metrics_available, s.metrics_beating_avg, s.is_hit, CASE WHEN s.is_noos = 1 THEN \'NOOS — Hit\' WHEN s.is_hit = 1 AND s.product_type = \'Established\' THEN \'Hit\' WHEN s.is_hit = 1 AND s.product_type = \'New\' THEN \'New — Early Hit Signal\' WHEN s.is_hit = 0 AND s.product_type = \'New\' THEN \'New\' ELSE \'Not a Hit\' END AS hit_label, coalesce(qty_available,0)+coalesce(qty_offline_available,0)+coalesce(qty_jit,0) inv FROM sku_level s left join (select * from snitch_db.maplemonk.cogs_daily_snapshot where date = (select max(date) from snitch_db.maplemonk.cogs_daily_snapshot)) a using(sku_group) ORDER BY s.l1_category, s.category, s.is_hit DESC, s.is_noos DESC, s.days_to_30pct ASC NULLS LAST ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            